//! Run with `cargo run -p serviceless --example service_macro`.

use async_trait::async_trait;
use serviceless::{service, Context, EmptyStream, Handler, Message, Service, TokioRuntime};

struct Counter(u32);

// Runtime, Stream, and metadata name are generated by the macro.
#[service]
impl Service for Counter {}

struct NamedService;

// A runtime type can be supplied as a quoted path. This alias uses Tokio for
// the example; an application can point it at its own Runtime implementation.
type AppRuntime = TokioRuntime;

#[service(runtime = "AppRuntime", name = "named_service")]
impl Service for NamedService {
    // An explicit Stream is preserved instead of the EmptyStream default.
    type Stream = EmptyStream<Self>;
}

#[derive(Message)]
#[message(result = u32)]
struct Add(u32);

#[async_trait]
impl Handler<Add> for Counter {
    async fn handle(&mut self, message: Add, _ctx: &mut Context<Self>) -> u32 {
        self.0 += message.0;
        self.0
    }
}

#[tokio::main]
async fn main() {
    let counter = Counter(0);
    assert_eq!(counter.metadata().name, "Counter");
    assert_eq!(NamedService.metadata().name, "named_service");

    let (address, run) = Context::new(&counter).run(counter);
    let task = tokio::spawn(run);

    assert_eq!(address.call(Add(2)).await.expect("counter call failed"), 2);
    address.close_service();
    task.await.expect("service task failed");

    println!("service macro example passed");
}
